{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "A highly transferable analogue with a piperidine and heteroaromatic amine was measured at 3% absolute oral bioavailability in humans, far below the 20% threshold, supporting low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "FK3453, a highly transferable heteroaromatic amine, was discontinued for unexpectedly poor human oral bioavailability attributed to aldehyde oxidase-mediated clearance; the query's primary aromatic amine/heteroaromatic core raises the same liability, supporting low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "DX-9065 showed only 3% oral bioavailability in fasted humans, directly matching the fasted condition and supporting a low prediction despite the query lacking its strong amidino groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Saquinavir, a highly transferable lipophilic drug, had absolute human oral bioavailability of 4% (range 1–9%), showing that high lipophilicity and poor solubility can keep F well below 20%; the query's high logP is a similar risk.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Emixustat, a lipophilic amino alcohol with high transferability, showed low oral bioavailability in healthy subjects, supporting low F for the query's lipophilic phenoxy-ether/amine scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues report low human oral bioavailability (mostly 1–4%, some <1%), consistently below the 20% threshold; the mixed physicochemical prior does not outweigh this convergent low-bioavailability evidence. Predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No experimental solubility or permeability data for the query; high logP is only a proxy.",
    "Potential aldehyde oxidase-mediated clearance of the primary aromatic amine/heteroaromatic core is not experimentally assessed.",
    "Fasted-state human PK data for the query are absent; extrapolation relies on high-transfer analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

